CREATE TABLE master_data (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category VARCHAR(40) NOT NULL, code VARCHAR(64) NOT NULL, name VARCHAR(190) NOT NULL, parent_id BIGINT UNSIGNED NULL, organisation_id BIGINT UNSIGNED NULL, is_active TINYINT NOT NULL DEFAULT 1, UNIQUE(category,code), FOREIGN KEY(parent_id) REFERENCES master_data(id), FOREIGN KEY(organisation_id) REFERENCES organisations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
